// personalBestWhereR holds the relationship-based filters of
// personalBestWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type personalBestWhereR[Q psql.Filterable] struct {
	cols personalBestColumns
}

// HasExercise filters parents that have a matching Exercise using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Exercises).
func (w personalBestWhereR[Q]) HasExercise(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Exercises.NameExpr()),
		sm.Where(Exercises.Columns.ID.EQ(w.cols.ExerciseID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasSet filters parents that have a matching Set using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Sets).
func (w personalBestWhereR[Q]) HasSet(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Sets.NameExpr()),
		sm.Where(Sets.Columns.ID.EQ(w.cols.SetID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// HasUser filters parents that have a matching User using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Users).
func (w personalBestWhereR[Q]) HasUser(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(Users.NameExpr()),
		sm.Where(Users.Columns.ID.EQ(w.cols.UserID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

func (o *PersonalBest) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "Exercise":
		rel, ok := retrieved.(*Exercise)
		if !ok {
			return fmt.Errorf("personalBest cannot load %T as %q", retrieved, name)
		}

		o.R.Exercise = rel
		o.R.Loaded.Exercise = true

		if rel != nil {
			rel.R.PersonalBests = PersonalBestSlice{o}
		}
		return nil
	case "Set":
		rel, ok := retrieved.(*Set)
		if !ok {
			return fmt.Errorf("personalBest cannot load %T as %q", retrieved, name)
		}

		o.R.Set = rel
		o.R.Loaded.Set = true

		if rel != nil {
			rel.R.PersonalBests = PersonalBestSlice{o}
		}
		return nil
	case "User":
		rel, ok := retrieved.(*User)
		if !ok {
			return fmt.Errorf("personalBest cannot load %T as %q", retrieved, name)
		}

		o.R.User = rel
		o.R.Loaded.User = true

		if rel != nil {
			rel.R.PersonalBests = PersonalBestSlice{o}
		}
		return nil
	default:
		return fmt.Errorf("personalBest has no relationship %q", name)
	}
}

type personalBestPreloader struct {
	Exercise func(...psql.PreloadOption) psql.Preloader
	Set      func(...psql.PreloadOption) psql.Preloader
	User     func(...psql.PreloadOption) psql.Preloader
}

func buildPersonalBestPreloader() personalBestPreloader {
	return personalBestPreloader{
		Exercise: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Exercise, ExerciseSlice](psql.PreloadRel{
				Name: "Exercise",
				Sides: []psql.PreloadSide{
					{
						From:        PersonalBests,
						To:          Exercises,
						FromColumns: []string{"exercise_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Exercises.Columns.Names(), exerciseScanMapperNullable, opts...)
		},
		Set: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Set, SetSlice](psql.PreloadRel{
				Name: "Set",
				Sides: []psql.PreloadSide{
					{
						From:        PersonalBests,
						To:          Sets,
						FromColumns: []string{"set_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Sets.Columns.Names(), setScanMapperNullable, opts...)
		},
		User: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*User, UserSlice](psql.PreloadRel{
				Name: "User",
				Sides: []psql.PreloadSide{
					{
						From:        PersonalBests,
						To:          Users,
						FromColumns: []string{"user_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Users.Columns.Names(), userScanMapperNullable, opts...)
		},
	}
}

type personalBestThenLoader[Q orm.Loadable] struct {
	Exercise func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Set      func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	User     func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildPersonalBestThenLoader[Q orm.Loadable]() personalBestThenLoader[Q] {
	type ExerciseLoadInterface interface {
		LoadExercise(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type SetLoadInterface interface {
		LoadSet(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type UserLoadInterface interface {
		LoadUser(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return personalBestThenLoader[Q]{
		Exercise: thenLoadBuilder[Q](
			"Exercise",
			func(ctx context.Context, exec bob.Executor, retrieved ExerciseLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadExercise(ctx, exec, mods...)
			},
		),
		Set: thenLoadBuilder[Q](
			"Set",
			func(ctx context.Context, exec bob.Executor, retrieved SetLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadSet(ctx, exec, mods...)
			},
		),
		User: thenLoadBuilder[Q](
			"User",
			func(ctx context.Context, exec bob.Executor, retrieved UserLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadUser(ctx, exec, mods...)
			},
		),
	}
}

// LoadExercise loads the personalBest's Exercise into the .R struct
func (o *PersonalBest) LoadExercise(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Exercise = nil
	o.R.Loaded.Exercise = false

	related, err := o.Exercise(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.PersonalBests = PersonalBestSlice{o}

	o.R.Exercise = related
	o.R.Loaded.Exercise = true
	return nil
}

// LoadExercise loads the personalBest's Exercise into the .R struct
func (os PersonalBestSlice) LoadExercise(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	exercises, err := os.Exercise(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Exercise = nil
		o.R.Loaded.Exercise = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	personalBestByKey := make(map[uuid.UUID][]*PersonalBest, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		personalBestByKey[o.ExerciseID] = append(personalBestByKey[o.ExerciseID], o)
	}

	for _, rel := range exercises {

		owners, ok := personalBestByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.Exercise != nil {
				continue
			}

			rel.R.PersonalBests = append(rel.R.PersonalBests, o)

			o.R.Exercise = rel

		}
	}

	return nil
}

