type personalBestJoins[Q dialect.Joinable] struct {
	typ      string
	Exercise modAs[Q, exerciseColumns]
	Set      modAs[Q, setColumns]
	User     modAs[Q, userColumns]
}

func (j personalBestJoins[Q]) aliasedAs(alias string) personalBestJoins[Q] {
	return buildPersonalBestJoins[Q](buildPersonalBestColumns(alias), j.typ)
}

func buildPersonalBestJoins[Q dialect.Joinable](cols personalBestColumns, typ string) personalBestJoins[Q] {
	return personalBestJoins[Q]{
		typ: typ,
		Exercise: modAs[Q, exerciseColumns]{
			c: Exercises.Columns,
			f: func(to exerciseColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Exercises.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.ExerciseID),
					))
				}

				return mods
			},
		},
		Set: modAs[Q, setColumns]{
			c: Sets.Columns,
			f: func(to setColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Sets.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.SetID),
					))
				}

				return mods
			},
		},
		User: modAs[Q, userColumns]{
			c: Users.Columns,
			f: func(to userColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Users.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.UserID),
					))
				}

				return mods
			},
		},
	}
}
